PREAMBLE = '\n#include "rflink.h"\n#include "rflink_engine.h"\n#include <Arduino.h>\n#include "esphome/core/log.h"\n#include <algorithm>\n#include <cassert>\n#include <iostream>\n#include <set>\nuint32_t test_millis=1000, probe_clock=0;\nesphome::rflink::RFLinkComponent rf_bridge;\nesphome::rflink_gestures::Button rf_gesture_1,rf_gesture_2;\nstruct Binary {\n bool state=false,have=false;\n bool has_state() const {return have;}\n void publish_state(bool value){have=true;state=value;}\n} rf_gesture_pressed_1,rf_gesture_pressed_2;\nstruct EventEntity {\n std::set<std::string> allowed;\n std::vector<std::string> events;\n void trigger(const std::string &type){assert(allowed.count(type));events.push_back(type);}\n int count(const std::string &type) const{return std::count(events.begin(),events.end(),type);}\n} rf_gesture_event_1,rf_gesture_event_2;\nstatic std::vector<int32_t> raw(uint32_t bits){\n std::vector<int32_t> v;\n for(int i=23;i>=0;--i){bool b=(bits>>i)&1;v.push_back(b?900:300);v.push_back(b?-300:-900);}\n v.push_back(300);v.push_back(-5000);return v;\n}\n'
TESTBODY = '\nunsigned json_count=0;\nstd::string last_json;\nvoid frame(uint32_t t,uint32_t bits=0x853728){\n test_millis=t;auto v=raw(bits);\n rf_bridge.on_receive(esphome::remote_base::RemoteReceiveData(v));\n tick_gestures();\n}\nvoid burst(uint32_t t,uint32_t span=80,uint32_t bits=0x853728){\n for(uint32_t dt=0;dt<=span;dt+=40)frame(t+dt,bits);\n}\nvoid end(uint32_t t){test_millis=t;tick_gestures();}\nvoid reset_case(){\n rf_gesture_1.cancel(test_millis);rf_gesture_2.cancel(test_millis);\n rf_gesture_event_1.events.clear();rf_gesture_event_2.events.clear();\n rflink_legacy::reset();json_count=0;\n}\nint main(){\n rf_bridge.setup();rf_bridge.set_decode_enabled(false);setup_gestures();\n rf_bridge.add_on_message_callback([](std::string s){++json_count;last_json=std::move(s);});\n burst(1000);end(2000);assert(json_count==0 && rf_gesture_event_1.events.empty());\n rf_bridge.set_decode_enabled(true);\n burst(3000,1600);end(5200);\n // Multiple legacy plugins share CRC state. Do not mistake that upstream\n // behavior for gesture counting; full sets can emit additional JSON.\n if (rflink_legacy::plugin_count()<=4) assert(json_count==1);\n else assert(json_count>=1);\n std::cout<<"hold_frames=41; legacy_json="<<json_count<<"; ";\n assert(rf_gesture_event_1.count("hold")==1);\n assert(rf_gesture_event_1.count("hold_repeat")>0);\n assert(rf_gesture_event_1.count("hold_release")==1);\n assert(rf_gesture_event_1.count("single")==0 && !rf_gesture_pressed_1.state);\n assert(rf_gesture_1.matching_frames()==41 && rf_gesture_2.matching_frames()==0);\n assert(last_json.find("\\"ID\\":\\"085372\\"")!=std::string::npos);\n reset_case();\n burst(6000);burst(6300);end(7100);\n assert(json_count>=1 && rf_gesture_event_1.count("double")==1);\n if (rflink_legacy::plugin_count()<=4) assert(json_count==1);\n assert(rf_gesture_event_1.count("single")==0);\n reset_case();\n burst(8000);burst(8300);burst(8600);end(9400);\n assert(json_count>=1 && rf_gesture_event_1.count("triple")==1);\n if (rflink_legacy::plugin_count()<=4) assert(json_count==1);\n assert(rf_gesture_event_1.count("double")==0 && rf_gesture_event_1.count("single")==0);\n reset_case();\n burst(10000,80,0x1fac28);end(10700);\n assert(rf_gesture_event_1.events.empty() && rf_gesture_event_2.count("single")==1);\n reset_case();\n burst(11000,80,0x853724);end(11800);\n assert(rf_gesture_event_1.events.empty() && rf_gesture_event_2.events.empty());\n reset_case();\n burst(12000);rf_bridge.set_decode_enabled(false);end(13000);\n assert(rf_gesture_event_1.count("cancel")==1 && rf_gesture_event_1.count("single")==0);\n assert(!rf_gesture_pressed_1.state);\n const auto observed=rf_bridge.get_observed_frames();\n burst(14000);assert(rf_bridge.get_observed_frames()==observed);\n rf_bridge.set_decode_enabled(true);end(15000);\n assert(rf_gesture_event_1.count("single")==0); // No replay on resume.\n rflink_legacy::FrameObservation obs;obs.valid=true;std::string json;\n assert(!rflink_legacy::decode({},json,&obs) && !obs.valid && json.empty());\n auto invalid=raw(0x853728);invalid[7]=0;obs.valid=true;\n assert(!rflink_legacy::decode(invalid,json,&obs) && !obs.valid);\n std::cout<<"PASS: actual YAML lambdas + real bridge + unmodified Plugin_061. "\n             "Suppressed RF repeats drive hold/double/triple; IDs, cancel and resume isolated.\\n";\n}\n'
